<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script>
<script>
const countries=@json($mapCountries),ports=@json($mapPorts),map=L.map('unifiedMap',{worldCopyJump:true,scrollWheelZoom:false,preferCanvas:true}).setView([18,10],2);L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',{maxZoom:18,attribution:'&copy; OpenStreetMap &copy; CARTO'}).addTo(map);const countryLayer=L.layerGroup(),portLayer=L.markerClusterGroup({showCoverageOnHover:false,maxClusterRadius:42,chunkedLoading:true,chunkInterval:120,chunkDelay:30,chunkProgress:(done,total)=>{const p=Math.round(done/total*100);document.getElementById('loadText').textContent=`${done.toLocaleString('id-ID')} / ${total.toLocaleString('id-ID')} ports (${p}%)`;document.getElementById('loadBar').style.width=p+'%';if(done===total)setTimeout(()=>document.getElementById('mapLoader').classList.add('done'),300)}}),countryEntries=[],portEntries=[];const levelClass=l=>'marker-'+l.toLowerCase(),esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));countries.forEach(c=>{const icon=L.divIcon({className:'',html:`<span class="country-marker ${levelClass(c.level)}">${Math.round(c.score)}</span>`,iconSize:[25,25]}),marker=L.marker([c.latitude,c.longitude],{icon,title:c.name}).bindPopup(`<strong>${esc(c.name)}</strong><br><small>${esc(c.capital)} · ${esc(c.region)}</small><br>Risk: ${c.score} · ${c.level}<br><a href="${c.url}">Country intelligence →</a>`);countryEntries.push({data:c,marker});countryLayer.addLayer(marker)});const portMarkers=ports.map(p=>{const icon=L.divIcon({className:'',html:`<span class="port-marker ${levelClass(p.level)}"></span>`,iconSize:[7,7]}),marker=L.marker([p.latitude,p.longitude],{icon,title:p.name}).bindPopup(`<strong>${esc(p.name)}</strong><br><small>${esc(p.city)}, ${esc(p.country)}</small><br>Risk: ${p.score} · ${p.level}<br><a href="${p.url}">Port intelligence →</a>`);portEntries.push({data:p,marker});return marker});portLayer.addLayers(portMarkers);map.addLayer(countryLayer);map.addLayer(portLayer);let activeRisk='All',showCountries=true,showPorts=true;const updateCount=()=>document.getElementById('visibleCount').textContent=((showCountries?countryEntries.filter(e=>activeRisk==='All'||e.data.level===activeRisk).length:0)+(showPorts?portEntries.filter(e=>activeRisk==='All'||e.data.level===activeRisk).length:0)).toLocaleString('id-ID');function apply(){countryLayer.clearLayers();portLayer.clearLayers();if(showCountries)countryEntries.filter(e=>activeRisk==='All'||e.data.level===activeRisk).forEach(e=>countryLayer.addLayer(e.marker));if(showPorts)portLayer.addLayers(portEntries.filter(e=>activeRisk==='All'||e.data.level===activeRisk).map(e=>e.marker));updateCount()}document.querySelectorAll('.layer-switch button').forEach(b=>b.onclick=()=>{b.classList.toggle('active');if(b.dataset.layer==='countries')showCountries=b.classList.contains('active');else showPorts=b.classList.contains('active');apply()});document.querySelectorAll('.risk-filter button').forEach(b=>b.onclick=()=>{activeRisk=b.dataset.risk;document.querySelectorAll('.risk-filter button').forEach(x=>x.classList.toggle('active',x===b));apply()});const input=document.getElementById('mapSearch'),results=document.getElementById('searchResults');input.oninput=()=>{const q=input.value.toLowerCase().trim();if(!q){results.classList.remove('show');return}const matches=[...countryEntries.map((e,i)=>({type:'country',i,e})),...portEntries.map((e,i)=>({type:'port',i,e}))].filter(x=>Object.values(x.e.data).some(v=>String(v).toLowerCase().includes(q))).slice(0,8);results.innerHTML=matches.map(x=>`<button data-type="${x.type}" data-index="${x.i}"><b>${x.type==='country'?'Country':'Port'}</b> · ${esc(x.e.data.name)}</button>`).join('');results.classList.add('show')};results.onclick=e=>{const b=e.target.closest('button');if(!b)return;const item=b.dataset.type==='country'?countryEntries[+b.dataset.index]:portEntries[+b.dataset.index];if(b.dataset.type==='port')portLayer.zoomToShowLayer(item.marker,()=>item.marker.openPopup());else{map.setView(item.marker.getLatLng(),5);item.marker.openPopup()}results.classList.remove('show')};document.getElementById('resetMap').onclick=()=>map.setView([18,10],2);updateCount();
const mapStage=document.getElementById('mapStage'),fullscreenButton=document.getElementById('mapFullscreen');fullscreenButton.addEventListener('click',async()=>{try{if(!document.fullscreenElement)await mapStage.requestFullscreen();else await document.exitFullscreen()}catch(error){console.error('Fullscreen is not available',error)}});document.addEventListener('fullscreenchange',()=>{const active=document.fullscreenElement===mapStage;fullscreenButton.querySelector('i').className=active?'fas fa-compress':'fas fa-expand';fullscreenButton.querySelector('span').textContent=active?'Exit fullscreen':'Fullscreen';fullscreenButton.title=active?'Exit fullscreen':'Open fullscreen map';setTimeout(()=>map.invalidateSize(),180)});
</script>
<script>
// Add a labelled Dark Matter basemap and remove the previous base layer.
const professionalWorldMap = L.tileLayer(
    'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',
    {
        maxZoom: 19,
        subdomains: 'abcd',
        attribution: '&copy; OpenStreetMap contributors &copy; CARTO',
    }
).addTo(map);
map.eachLayer(layer => {
    if (layer instanceof L.TileLayer && layer !== professionalWorldMap) {
        map.removeLayer(layer);
    }
});
L.control.scale({ imperial: false, position: 'bottomright' }).addTo(map);
portLayer.options.disableClusteringAtZoom = 7;
portLayer.options.spiderfyOnMaxZoom = true;
portLayer.options.zoomToBoundsOnClick = true;
</script>
@stop
